      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 20px;
    }
    .card {
      width: min(92vw, 420px);
      background: rgba(255,255,255,0.86);
      border: 2px solid rgba(255,255,255,0.72);
      border-radius: 24px;
      padding: 22px 18px;
      box-shadow: 0 12px 36px rgba(17, 63, 97, 0.18);
      text-align: center;
      pointer-events: auto;
    }
    h1 {
      margin: 0 0 8px;
      font-size: 30px;
      line-height: 1.1;
    }
    p {
      margin: 8px 0;
      font-size: 16px;
      line-height: 1.5;
    }
    .btn {
      margin-top: 14px;
      border: 0;
      border-radius: 999px;
      background: linear-gradient(180deg, #ffd36a, #ffb84d);
      color: #5b3900;
      font-weight: 800;
      font-size: 18px;
      padding: 14px 28px;
      min-width: 160px;
