    }
    .hint {
      font-size: 14px;
      opacity: 0.85;
    }
  </style>
</head>
<body>
  <canvas id="game"></canvas>
  <div class="ui">
    <div class="topbar">
      <div class="pill">得分 <span id="score">0</span></div>
      <div class="pill">生命 <span id="lives">3</span></div>
    </div>
    <div class="center" id="overlay">
      <div class="card">
        <h1>猫咪接鱼</h1>
        <p>左右移动小猫，接住从天而降的小鱼。</p>
        <p>漏掉太多鱼游戏就结束。</p>
        <p class="hint">支持触摸、鼠标与方向键</p>
        <button class="btn" id="startBtn">开始游戏</button>
      </div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    const scoreEl = document.getElementById('score');
    const livesEl = document.getElementById('lives');
    const overlay = document.getElementById('overlay');
    const startBtn = document.getElementById('startBtn');

    let vw = 0, vh = 0, dpr = Math.min(window.devicePixelRatio || 1, 2);
    function resize() {
      vw = window.innerWidth;
      vh = window.innerHeight;
      canvas.width = Math.floor(vw * dpr);
      canvas.height = Math.floor(vh * dpr);
      canvas.style.width = vw + 'px';
      canvas.style.height = vh + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    }
    resize();
    window.addEventListener('resize', resize);

    const game = {
      running: false,
      score: 0,
      lives: 3,
      time: 0,
      spawnTimer: 0,
      speedScale: 1,
      pointerX: null,
      moveDir: 0,
      fish: [],
      particles: [],
      cat: {
        x: 0,
        y: 0,
        w: 92,
        h: 64,
        speed: 520
      }
    };

    function resetGame() {
      game.running = true;
      game.score = 0;
      game.lives = 3;
      game.time = 0;
      game.spawnTimer = 0;
      game.speedScale = 1;
      game.pointerX = null;
      game.moveDir = 0;
      game.fish = [];
      game.particles = [];
      game.cat.w = Math.min(96, vw * 0.24);
      game.cat.h = game.cat.w * 0.72;
      game.cat.x = vw / 2;
      game.cat.y = vh - Math.max(90, vh * 0.12);
      updateUI();
      overlay.style.display = 'none';
    }

    function updateUI() {
      scoreEl.textContent = game.score;
      livesEl.textContent = game.lives;
    }

    function spawnFish() {
      const size = 18 + Math.random() * 14;
      game.fish.push({
        x: 24 + Math.random() * (vw - 48),
        y: -30,
        size,
        speed: (180 + Math.random() * 120) * game.speedScale,
        sway: Math.random() * Math.PI * 2,
        swaySpeed: 1 + Math.random() * 2,
        rot: (Math.random() - 0.5) * 0.6
      });
    }

    function burst(x, y, color, count) {
      for (let i = 0; i < count; i++) {
        const a = Math.random() * Math.PI * 2;
        const s = 40 + Math.random() * 120;
        game.particles.push({
          x, y,
          vx: Math.cos(a) * s,
          vy: Math.sin(a) * s,
          life: 0.5 + Math.random() * 0.35,
          maxLife: 0.5 + Math.random() * 0.35,
          r: 3 + Math.random() * 4,
          color
        });
      }
    }

    function endGame() {
      game.running = false;
      overlay.innerHTML = '<div class="card">'
        + '<h1>游戏结束</h1>'
        + '<p>你接住了 <strong>' + game.score + '</strong> 条小鱼。</p>'
        + '<p class="hint">再来一局，看看能不能接得更多。</p>'
        + '<button class="btn" id="restartBtn">重新开始</button>'
        + '</div>';
      overlay.style.display = 'flex';
      document.getElementById('restartBtn').addEventListener('click', resetGame, { once: true });
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function update(dt) {
      if (!game.running) return;

      game.time += dt;
      game.speedScale = 1 + Math.min(1.8, game.time * 0.025);
      game.spawnTimer -= dt;
      const spawnGap = Math.max(0.28, 0.9 - game.time * 0.02);
      if (game.spawnTimer <= 0) {
        spawnFish();
        if (Math.random() < Math.min(0.35, game.time * 0.01)) spawnFish();
        game.spawnTimer = spawnGap;
      }

      const catHalf = game.cat.w / 2;
      if (game.pointerX !== null) {
        const diff = game.pointerX - game.cat.x;
        game.cat.x += diff * Math.min(1, dt * 10);
      } else if (game.moveDir !== 0) {
        game.cat.x += game.moveDir * game.cat.speed * dt;
      }
      game.cat.x = clamp(game.cat.x, catHalf + 8, vw - catHalf - 8);
      game.cat.y = vh - Math.max(86, vh * 0.12);

      for (let i = game.fish.length - 1; i >= 0; i--) {
        const f = game.fish[i];
        f.y += f.speed * dt;
        f.x += Math.sin(game.time * f.swaySpeed + f.sway) * 35 * dt;

        const catchZoneY = game.cat.y - game.cat.h * 0.12;
        const dx = Math.abs(f.x - game.cat.x);
        const dy = Math.abs(f.y - catchZoneY);
        if (dx < game.cat.w * 0.42 && dy < game.cat.h * 0.34 + f.size * 0.4) {
          game.fish.splice(i, 1);
          game.score += 1;
          updateUI();
          burst(f.x, f.y, '#24b36b', 8);
          continue;
        }

        if (f.y > vh + 40) {
          game.fish.splice(i, 1);
          game.lives -= 1;
          updateUI();
          burst(f.x, vh - 30, '#ff6b6b', 10);
          if (game.lives <= 0) {
            endGame();
            return;
          }
        }
      }

      for (let i = game.particles.length - 1; i >= 0; i--) {
        const p = game.particles[i];
        p.life -= dt;
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.vy += 180 * dt;
        p.vx *= 0.99;
        if (p.life <= 0) game.particles.splice(i, 1);
      }
    }

    function drawFish(x, y, size, rot) {
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(rot);
      ctx.fillStyle = '#5fa8ff';
      ctx.beginPath();
      ctx.ellipse(0, 0, size, size * 0.58, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(-size * 0.9, 0);
      ctx.lineTo(-size * 1.55, -size * 0.55);
      ctx.lineTo(-size * 1.55, size * 0.55);
      ctx.closePath();
      ctx.fillStyle = '#7dc2ff';
      ctx.fill();
      ctx.fillStyle = '#eaf7ff';
      ctx.beginPath();
      ctx.arc(size * 0.45, -size * 0.08, size * 0.12, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#17324d';
      ctx.beginPath();
      ctx.arc(size * 0.48, -size * 0.08, size * 0.05, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    function drawCat() {
      const { x, y, w, h } = game.cat;
      ctx.save();
      ctx.translate(x, y);

      ctx.fillStyle = '#f5ae62';
      ctx.beginPath();
      ctx.roundRect(-w * 0.5, -h * 0.42, w, h * 0.78, h * 0.25);
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(-w * 0.32, -h * 0.16);
      ctx.lineTo(-w * 0.14, -h * 0.62);
      ctx.lineTo(0, -h * 0.2);
      ctx.closePath();
      ctx.fill();

      ctx.beginPath();
      ctx.moveTo(w * 0.32, -h * 0.16);
      ctx.lineTo(w * 0.14, -h * 0.62);
      ctx.lineTo(0, -h * 0.2);
      ctx.closePath();
      ctx.fill();

      ctx.fillStyle = '#ffd7b0';
      ctx.beginPath();
      ctx.ellipse(0, -h * 0.04, w * 0.28, h * 0.2, 0, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#17324d';
      ctx.beginPath();
      ctx.arc(-w * 0.16, -h * 0.12, w * 0.045, 0, Math.PI * 2);
      ctx.arc(w * 0.16, -h * 0.12, w * 0.045, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = '#17324d';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, -h * 0.02);
      ctx.lineTo(-w * 0.06, h * 0.04);
      ctx.lineTo(0, h * 0.08);
      ctx.lineTo(w * 0.06, h * 0.04);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(-w * 0.22, 0);
      ctx.lineTo(-w * 0.38, -h * 0.03);
      ctx.moveTo(-w * 0.22, h * 0.06);
      ctx.lineTo(-w * 0.4, h * 0.08);
      ctx.moveTo(w * 0.22, 0);
      ctx.lineTo(w * 0.38, -h * 0.03);
      ctx.moveTo(w * 0.22, h * 0.06);
      ctx.lineTo(w * 0.4, h * 0.08);
      ctx.stroke();

      ctx.restore();
    }

    function drawBackground() {
      ctx.clearRect(0, 0, vw, vh);

      const g = ctx.createLinearGradient(0, 0, 0, vh);
      g.addColorStop(0, '#8fd3ff');
      g.addColorStop(1, '#effbff');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, vw, vh);

      ctx.fillStyle = 'rgba(255,255,255,0.45)';
      for (let i = 0; i < 3; i++) {
        const cx = (vw * (0.2 + i * 0.32)) + Math.sin(game.time * 0.15 + i) * 18;
        const cy = vh * (0.16 + i * 0.05);
        ctx.beginPath();
        ctx.arc(cx, cy, 24, 0, Math.PI * 2);
        ctx.arc(cx + 22, cy + 3, 18, 0, Math.PI * 2);
        ctx.arc(cx - 22, cy + 5, 16, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.fillStyle = '#d0f0ff';
      ctx.fillRect(0, vh - 48, vw, 48);
      ctx.fillStyle = '#b4e38c';
      ctx.fillRect(0, vh - 34, vw, 34);
    }

    function draw() {
      drawBackground();
      for (const f of game.fish) drawFish(f.x, f.y, f.size, f.rot + Math.sin(game.time * 8 + f.sway) * 0.15);
      drawCat();
      for (const p of game.particles) {
        ctx.globalAlpha = Math.max(0, p.life / p.maxLife);
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min(0.033, (now - last) / 1000);
      last = now;
      update(dt);
      draw();
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);

    function setPointer(clientX) {
      game.pointerX = clientX;
    }

    window.addEventListener('pointerdown', (e) => {
      setPointer(e.clientX);
    }, { passive: true });

    window.addEventListener('pointermove', (e) => {
      if (e.buttons || e.pointerType === 'touch') setPointer(e.clientX);
    }, { passive: true });

    window.addEventListener('pointerup', () => {
      game.pointerX = null;
    }, { passive: true });

    window.addEventListener('pointercancel', () => {
      game.pointerX = null;
    }, { passive: true });

    window.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') game.moveDir = -1;
      if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') game.moveDir = 1;
      if ((e.key === 'Enter' || e.key === ' ') && !game.running) resetGame();
    });

    window.addEventListener('keyup', (e) => {
      if (['ArrowLeft', 'a', 'A', 'ArrowRight', 'd', 'D'].includes(e.key)) game.moveDir = 0;
    });

    startBtn.addEventListener('click', resetGame);

    if (!CanvasRenderingContext2D.prototype.roundRect) {
      CanvasRenderingContext2D.prototype.roundRect = function(x, y, w, h, r) {
        r = Math.min(r, w / 2, h / 2);
        this.beginPath();
        this.moveTo(x + r, y);
        this.arcTo(x + w, y, x + w, y + h, r);
        this.arcTo(x + w, y + h, x, y + h, r);
        this.arcTo(x, y + h, x, y, r);
        this.arcTo(x, y, x + w, y, r);
        this.closePath();
        return this;
      };
    }
  </script>
</body>
</html>"}

